/* Integration of the approved character studio with the existing product journeys. */
window.EchoCastContext={state:()=>state,person:i=>getPerson(i),current:()=>current()};
const castProfile=profile;
profile=function(i){if(i!==4)return castProfile(i);modal(`<span class="eyebrow">Moderator</span><h2 id="modal-title">Meet ECHO.</h2><div class="avatar-preview">${face(4)}</div><p>Keeps the conversation moving, asks for evidence, and gives each perspective room to be heard.</p><div class="note">The moderator and panel use authored dialogue in this preview. Source checks are examples, not live verification.</div><div class="modal-actions"><button class="primary" id="host-return">Back to the conversation</button></div>`);$('#host-return').onclick=close};
const castUpdateTurn=updateTurn;
updateTurn=function(){castUpdateTurn();if(!$('#stage'))return;$('#play').textContent=state.playing?'Pause':'Play';$('#sound').textContent=state.voice?'Mute':'Sound';$('#next').textContent='Next';$('#finish').textContent='Recap';const host=typeof current()[0]!=='number';$$('[data-person]').forEach(c=>{c.classList.toggle('speaking',host?+c.dataset.person===4:+c.dataset.person===(current()[0]===2&&state.onStage?3:current()[0]));c.setAttribute('aria-label','View '+getPerson(+c.dataset.person).name+' profile')})};
const castRender=render;
render=function(){castRender();polishPlatform()};
function polishPlatform(){if($('#stage'))updateTurn();$('#main').setAttribute('tabindex','-1');const createButton=$('#create-top');if(createButton)createButton.textContent='Create a mind';const activityButton=$('#activity');if(activityButton)activityButton.textContent='Activity';const profileButton=$('#spotlight-profile');if(profileButton){profileButton.textContent='Meet';profileButton.setAttribute('aria-label','Meet featured character')}const sound=$('#sound');if(sound)sound.setAttribute('aria-label',state.voice?'Mute device voice':'Enable device voice');const next=$('#next');if(next)next.textContent='Next';const finish=$('#finish');if(finish)finish.textContent='Recap';const egg=$('#egg');if(egg)egg.textContent='Toss an egg';const gift=$('#gift');if(gift)gift.textContent='Send a gift';const lab=$('.lab-entry');if(lab)lab.innerHTML='<span>Character studio</span><strong>Direct Nova’s performance</strong><span>Open studio</span>';}
window.addEventListener('echo:portrait-error',()=>toast('3D portraits could not load. Reload to try again. The conversations and creator tools are still available.'));
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(window.speechSynthesis)speechSynthesis.cancel();window.EchoCast?.setSpeech(false);if(state.view==='watch'){state.playing=false;updateTurn()}}});
// Keep the prototype disclosure accurate without cluttering the stage.
$('#about').onclick=()=>modal(`<span class="eyebrow">About ECHO</span><h2 id="modal-title">Different minds. A shared stage.</h2><p>Watch a conversation, ask a question, follow a perspective, or create a character of your own.</p><div class="note">This is a prototype. Dialogue, audience activity, polls and credits are illustrative. Your character and progress are saved on this device. No real payments or live AI are connected.</div><p>The cast shares a CC0 base rig with distinct styling. The panel’s optional audio uses your device voice. Nova’s character studio uses recorded speech with phoneme timing.</p><a class="source-link" href="lab/assets/ATTRIBUTION.txt" target="_blank" rel="noopener">Character and software credits</a><a class="source-link" href="lab/">Open Nova’s character studio</a>`);
polishPlatform();initFaces();
